  "m1294": "تمت مراجعة مراحل القرار وأحكام الحقوق",
  "m1295": "تضع حقوق الإنسان والأخلاقيات ضمن عملية مستمرة لجمع المعلومات وتقييم المخاطر والنظر في البيئة العملية وتحديد الخيارات والتصرف والمراجعة.",
  "m1296": "تمت مراجعة النسخة العامة. يجب على الأفراد التحقق من التعليمات الداخلية الحالية المنطبقة. هذه اللعبة ليست تطبيقًا رسميًا أو تقييمًا رسميًا.",
  "m1297": "أدرج العودة إلى الأدلة عند وصول معلومات جديدة، واشرح الخيار المحدد.",
