  "m1306": "FRA · التنميط غير المشروع",
  "m1307": "Preventing unlawful profiling today and in the future: a guide",
  "m1308": "وكالة الاتحاد الأوروبي للحقوق الأساسية",
  "m1309": "دليل FRA",
  "m1310": "إرشادات أوروبية",
  "m1311": "الاتحاد الأوروبي",
  "m1312": "تمت مراجعة النظرة العامة للدليل ومبادئه الرئيسية",
  "m1313": "تشرح التنميط التمييزي وضرورة الاستخدام المشروع والضروري والمتناسب للمعلومات. لا يجوز أن تكون الخصائص المحمية السبب الوحيد أو الرئيسي لاختيار شخص.",
  "m1314": "الإرشادات الأوروبية لا تمنح بحد ذاتها صلاحية تفتيش أيرلندية. الوصف المحدد وذو الصلة لمشتبه به يختلف عن الصورة النمطية العامة لجماعة.",
