  "m1322": "عرض يشمل الاتحاد الأوروبي؛ تختلف المؤسسات الوطنية والبيانات المتاحة.",
  "m1323": "عامل القرارات الفردية والإشراف والظروف التنظيمية كموضوعات تعلم مترابطة.",
  "m1324": "INAR / ICCL · بحث مجتمعي",
