  "m1328": "بحث مجتمعي",
  "m1329": "تمت مراجعة المناهج والنتائج ذات الصلة",
  "m1330": "يجمع بين البحث المكتبي والمشاركة التشاركية في موضوع التنميط العنصري وتجارب التعامل مع الشرطة.",
  "m1331": "تقدم روايات المشاركين أدلة وأولويات مرتبطة بسياقها؛ ولا يقدّر أسلوب أخذ العينة مدى الانتشار على المستوى الوطني.",
  "m1332": "اعترف بالتجربة التراكمية للإيقاف المتكرر وأدرج مساهمة المجتمع في التطوير اللاحق.",
  "m1333": "O’Brien-Olinger · ثقافة الشرطة الأيرلندية",
  "m1334": "Police, Race and Culture in the ‘New Ireland’: An Ethnography",
  "m1335": "Sam O’Brien-Olinger",
  "m1336": "Palgrave Macmillan",
  "m1337": "كتاب أكاديمي",
  "m1338": "وصف الناشر والسجل الببليوغرافي؛ لم يُراجع الكتاب كاملًا",
  "m1339": "دراسة إثنوغرافية لكيفية فهم أفراد Gardaí مجتمعات الأقليات المهاجرة والحديث عنها والتفاعل معها.",
  "m1340": "بحث نوعي تاريخي. لا يمكنه إثبات مدى انتشار الممارسات الحالية. مؤلفه هو أيضًا منشئ هذا المشروع.",
  "m1341": "افحص الافتراضات غير الرسمية وثقافة العمل؛ واطلب مراجعة مستقلة لتفسير اللعبة.",
