  "m1344": "Aogán Mulcahy",
  "m1345": "Criminology & Criminal Justice",
  "m1346": "مقال أكاديمي",
  "m1347": "تمت مراجعة ملخص الناشر",
  "m1348": "يفحص التنظيم المكاني والتهميش وعلاقات الشرطة مع الرحّل الأيرلنديين.",
  "m1349": "عرض نوعي مرتبط بسياقه التاريخي؛ وليس مقياسًا لسلوك أي فرد من Garda.",
  "m1350": "شكّك في افتراض أن شخصًا مثير للاشتباه لأنه يُنظر إليه على أنه في غير مكانه.",
  "m1351": "Joyce وزملاؤها · الوصول إلى العدالة",
  "m1352": "Irish Travellers’ Access to Justice",
  "m1353": "Sindy Joyce، Olive O’Reilly، Margaret O’Brien، David Joyce، Jennifer Schweppe وAmanda Haynes",
  "m1354": "تقرير بحثي من جامعة ليمريك",
  "m1355": "تمت مراجعة المستودع وعرض الجامعة للمشروع",
  "m1356": "يوثق تجارب الرحّل وتصوراتهم عن نظام العدالة الجنائية في أيرلندا.",
