  "m1553": "تمت مراجعة الملخص والنتائج في مستودع الجامعة",
  "m1554": "وجدت منافع وسطية للتعلم والاحتفاظ بالمعرفة، دون أفضلية تحفيزية موثوقة. كان التعليم المكمل والجلسات المتكررة والتعلم الجماعي عوامل معدلة ذات صلة.",
  "m1555": "ليست مراجعة لتدريب Garda ولا دليلًا على الانتقال إلى قرارات فعلية بالإيقاف والتفتيش.",
  "m1556": "قدّم الشروح وإعادة اللعب ونقاش الميسّر، ثم قيّم المنتج بدلًا من افتراض فعاليته.",
  "m1557": "Tansill وTankebe · تقييم اللقاءات",
