  "m1560": "إنجلترا",
  "m1561": "تمت مراجعة ملخص الناشر والمقدمة",
  "m1562": "تفحص 140 لقاءً مصورًا بكاميرات تُرتدى على الجسم. اختلفت التقييمات بحسب السياق ومجموعة المقيمين؛ وكان مشرفو الشرطة أكثر نقدًا من مقيمي الجمهور في بعض الجوانب.",
  "m1563": "عينة رصدية محدودة. لا ينبغي افتراض أن تقييمات الجمهور أو الشرطة توفر معيارًا كاملًا أو محايدًا لكل سياق.",
  "m1564": "حدّد ما يقيّمه المراجعون وقارن وجهات النظر بشأن المعاملة، بدلًا من اعتبار تقييم جماعة واحدة نهائيًا.",
