  "m1726": "تابع كفرد من الجمهور",
  "m1727": "أعد النظر في هذه الإجابة",
  "m1728": "→ عُد إلى المرحلة السابقة",
  "m1729": "التبديل يقارن الاستجابات للحظة نفسها. المتابعة تسلك المسار المحدد للدور النشط؛ وتُحفظ الإجابة الأخرى للتأمل. المشهد التالي خيالي ولا يتنبأ بسلوك أي شخص.",
  "m1730": "نقطة واحدة لاختيار يدعم حلًا مناسبًا وفق هذه الوقائع؛ و0 عندما يحتاج الاستدلال إلى مراجعة. يقيس هذا التعلم، لا التحيز الشخصي ولا المسؤولية عن سلوك شخص آخر.",
  "m1731": "يُحفظ تقدمك في هذا المتصفح. استخدم زر تبديل الموقع لنقله إلى الموقع المقابل.",
  "m1732": "الحفظ في المتصفح غير متاح. يُحتفظ بتقدمك خلال هذه الزيارة؛ ولا يزال زر تبديل الموقع قادرًا على نقله.",
  "m1733": "التقدم المحفوظ",
  "m1734": "نقاطك وملخص تأملاتك",
  "m1735": "موقف واحد.",
  "m1736": "ماذا كشف كل جانب؟",
  "m1737": "اكتمل المسار بهذا الدور.",
  "m1738": "أفضل مسار مكتمل",
