  "m1741": "أعد اللعب كفرد من الجمهور",
  "m1742": "لم تجب عن هذه المرحلة بهذا الدور.",
  "m1743": "أعد اللعب من هذه المرحلة كفرد Garda",
  "m1744": "أعد اللعب من هذه المرحلة كفرد من الجمهور",
  "m1745": "بدّل منظور الملخص",
  "m1746": "عرض كل التقدم",
  "m1747": "سجل تعلمك",
  "m1748": "النقاط والتقدم",
  "m1749": "أحرز تقدمًا بصورة منفصلة كفرد من الجمهور وكفرد Garda. عُد إلى اختيار لتحسين فهمك؛ ولا يمكن للمرحلة نفسها كسب أكثر من نقطة محفوظة واحدة لكل دور.",
  "m1750": "العب كفرد Garda",
  "m1751": "العب كفرد من الجمهور",
  "m1752": "كيف تُحسب نتيجتك",
  "m1753": "تمنح كل مرحلة نقطة واحدة لاستجابة تدعم حلًا مناسبًا وفق شرحها ومصادرها، أو 0 لاستجابة تحتاج إلى مراجعة. قد يكسب أكثر من اختيار نقطة. لا تُخصم نقاط لأخذ وقتك أو تبديل الأدوار.",
  "m1754": "يعرض المسار الحالي النقاط من مجموع القرارات التي أجبت عنها. تتطلب نتيجة الدور المكتمل إجابة بهذا الدور في كل مرحلة من المسار. تُستخدم النسب المئوية لأفضل النتائج المكتملة لأن أطوال المسارات قد تختلف.",
  "m1755": "تحتسب نقاط التعلم المحفوظة أفضل نتيجة لك في كل مرحلة فريدة، لذا لا يزيد تكرار المرحلة المجموع بصورة مصطنعة. تحسين إجابة من 0 إلى 1 يحدّث تقدمك.",
  "m1756": "النتيجة ليست مقياسًا لتحيز الشخص أو مؤهلًا مهنيًا أو توقعًا للقاء حقيقي. تبقى حقوق الإنسان والحقوق المدنية نفسها مهما كانت النتيجة.",
  "m1757": "العب بهذا الدور",
  "m1758": "إدارة تقدمك",
  "m1759": "تُحفظ محليًا خيارات اللعبة الخيالية ونقاطها فقط. لا يوجد حساب أو رفع بيانات. عند استخدام زر تبديل الموقع، تنقل اللعبة التقدم في جزء الرابط بعد علامة # وتدمجه مع تقدم الموقع الآخر المحفوظ. قد يشارك نسخ الرابط سجل التعلم المضمّن. لا تتزامن المتصفحات والأجهزة المنفصلة تلقائيًا.",
  "m1760": "هل تريد مسح النقاط وموضع الاستئناف المحفوظين على هذا الموقع في هذا المتصفح؟ قد يحتفظ الموقع المقابل والروابط المنسوخة سابقًا بنسخها الخاصة.",
  "m1761": "مسح التقدم المحفوظ لهذا الموقع",
  "m1762": "الاحتفاظ بالتقدم",
  "m1763": "مُسح تقدمك المحفوظ على هذا الموقع.",
  "m1764": "تعذر فتح هذا الموقف",
  "m1765": "لم يُعثر على هذه الصفحة.",
  "m1766": "تعذرت قراءة التقدم في هذا الرابط.",
  "m1767": "رابط هذا الموقف غير مكتمل أو من إصدار غير مدعوم. لا تزال نقاطك المحفوظة متاحة.",
  "m1768": "اختر موقفًا",
  "m1769": "نموذج أولي لمنصة تعليمية مستقلة.",
  "m1770": "معلومات عامة، وليست مشورة قانونية. هذا الموقع غير معتمد من أي منظمة أو من الشرطة الأيرلندية (An Garda Síochána).",
  "m1771": "تعلم تأملي، وليس إرشادًا عمليًا. مستقل؛ وغير معتمد من An Garda Síochána أو INAR أو ICCL. © 2026 Sam O’Brien-Olinger.",
