  "m1830": "موارد حقوق الإنسان والحقوق المدنية",
  "m1831": "افتح النسخة المشتركة لمقارنة المنظورين.",
  "m1832": "استخدم التدريب الفردي لنقاش مركز على دور واحد بالإنجليزية. اختر اللعبة المشتركة أعلاه لمقارنة المنظورين بالإنجليزية أو الأيرلندية.",
  "m1833": "يُحفظ تقدمك في هذا المتصفح. استخدم رابط موقع الموارد لنقله إلى الموقع المقابل.",
  "m1834": "الحفظ في المتصفح غير متاح. يُحتفظ بتقدمك خلال هذه الزيارة؛ ولا يزال رابط موقع الموارد قادرًا على نقله.",
  "m1835": "تُحفظ محليًا خيارات اللعبة الخيالية ونقاطها فقط. لا يوجد حساب أو رفع بيانات. عند استخدام رابط موقع الموارد، تنقل اللعبة التقدم في جزء الرابط بعد # وتدمجه مع تقدم الموقع الآخر المحفوظ. قد يشارك نسخ الرابط سجل التعلم المضمّن. لا تتزامن المتصفحات والأجهزة المنفصلة تلقائيًا.",
  "m1836": "اقرأ موقفًا، واختر استجابة، ثم اكتشف لماذا تهم.",
  "m1837": "الموقف {count}",
  "m1838": "استكشف هذا الموقف: إيقافك في الشارع",
