  "m2038": "تتعلق الشروح بالوقائع المذكورة في هذا التمرين. ولا تحدد مشروعية حادثة حقيقية أو تشخّص مواقف المتعلم.",
  "m2039": "اقرأ الاستدلال ثم تابع.",
