  "m2048": "فرد Garda في دورية",
  "m2049": "يسجّل هذا الملخص خيارات في تمرين خيالي. وليس مؤهلًا أو تقييمًا للأداء أو مقياسًا للتحيز الشخصي.",
  "m2050": "جرّب منظورًا آخر",
  "m2051": "أعد اللعب باختيار مختلف. لاحظ ما يتغير في المشهد التالي وما يبقى جزءًا من المعيار القانوني ومعيار الأدلة.",
