  "m2060": "Stopped: Both Sides | منظور Garda",
  "m2061": "الصفحة الرئيسية لمنظور Garda",
  "m2062": "ادخل دور Garda. افحص أسبابك. تأمل في قرارك.",
  "m2063": "تحتاج هذه اللعبة إلى JavaScript. لا يزال بإمكانك قراءة",
  "m2064": "و",
  "m2065": "دليل FRA لمنع التنميط غير المشروع",
